import{_ as e,c as r,o as a,aj as h,ao as o,aB as c}from"./chunks/framework.C2N4vG9O.js";const _=JSON.parse('{"title":"项目介绍","description":"Torch-RecHub 项目架构、特性和设计原理概览","frontmatter":{"title":"项目介绍","description":"Torch-RecHub 项目架构、特性和设计原理概览"},"headers":[],"relativePath":"zh/guide/intro.md","filePath":"zh/guide/intro.md"}'),d={name:"zh/guide/intro.md"};function i(l,t,s,n,u,p){return a(),r("div",null,[...t[0]||(t[0]=[h('<h1 id="项目介绍" tabindex="-1">项目介绍 <a class="header-anchor" href="#项目介绍" aria-label="Permalink to “项目介绍”">​</a></h1><p>Torch-RecHub 用 PyTorch 实现了召回、排序、多任务和生成式推荐模型。第一次用，可以拿仓库自带的广告点击样本训练 DeepFM，看看一条曝光记录怎样变成一个点击概率。<a href="/torch-rechub/zh/guide/quick_start.html">快速开始</a></p><p><img src="'+o+'" alt="Torch-RecHub 横幅" title="Torch-RecHub 横幅"></p><h2 id="框架架构" tabindex="-1">框架架构 <a class="header-anchor" href="#框架架构" aria-label="Permalink to “框架架构”">​</a></h2><p><img src="'+c+'" alt="Torch-RecHub 框架架构图"></p><p>用自己的数据训练时，有三处代码最值得看。特征定义告诉模型读哪些列，例如 <code>item_id</code> 用来查嵌入表，<code>price</code> 直接作为数值输入。模型的 <code>forward</code> 决定怎样组合这些输入。训练器负责按批训练、计算验证指标和保存权重。想改某个模型，可以从它的 <code>forward</code> 读起。<a href="/torch-rechub/zh/core/features.html">特征定义</a> · <a href="/torch-rechub/zh/core/evaluation.html">训练与评估</a></p><h2 id="按任务选择模型" tabindex="-1">按任务选择模型 <a class="header-anchor" href="#按任务选择模型" aria-label="Permalink to “按任务选择模型”">​</a></h2><table tabindex="0"><thead><tr><th>手上的问题</th><th>从哪里开始</th></tr></thead><tbody><tr><td>商品库里有很多商品，先为每个用户挑出一批候选</td><td><a href="/torch-rechub/zh/tutorials/retrieval.html">用 DSSM 做召回</a></td></tr><tr><td>已经有了候选，希望用户最可能点击的排在前面</td><td><a href="/torch-rechub/zh/tutorials/ctr.html">用 DeepFM 做排序</a></td></tr><tr><td>同一次曝光既有点击标签，也有购买标签</td><td><a href="/torch-rechub/zh/tutorials/pipeline.html">多任务学习</a></td></tr><tr><td>有按时间排列的交互记录，希望预测下一件物品</td><td><a href="/torch-rechub/zh/models/generative.html">序列与生成式模型</a></td></tr></tbody></table><p>例子可以在 CPU 上运行。使用 NVIDIA GPU、AMD GPU 或华为昇腾 NPU 时，先按设备安装对应的 PyTorch。模型训练好后，排序模型可以导出为 ONNX 做预测，双塔模型还可以分别导出用户和物品向量做检索。<a href="/torch-rechub/zh/guide/install.html">安装指南</a> · <a href="/torch-rechub/zh/serving/demo.html">部署示例</a></p>',9)])])}const b=e(d,[["render",i]]);export{_ as __pageData,b as default};
